    res=np.zeros_like(I,bool)
    dirs=((0,1),(1,0))+(((1,1),(1,-1)) if diags else ())
    for i in range(H):
        for j in range(W):
            if I[i,j]!=1: continue
            for d in dirs:
                def sees(dy,dx):
                    k=1
                    while True:
                        y,x=i+dy*k,j+dx*k
                        if not(0<=y<H and 0<=x<W): return False
                        if I[y,x]==2: return True
                        if I[y,x]!=1: return False
                        k+=1
                if sees(*d) and sees(-d[0],-d[1]):
                    res[i,j]=True; break
    return res
