def rule_cap(I, maxgap=5):
    H,W=I.shape
    res=np.zeros_like(I,bool)
    for i in range(H):
        for j in range(W):
            if I[i,j]!=1: continue
            for d in ((0,1),(1,0)):
                def sees(dy,dx):
                    k=1
                    while True:
                        y,x=i+dy*k,j+dx*k
                        if not(0<=y<H and 0<=x<W): return False
                        if I[y,x]==2: return k-1<=maxgap
                        if I[y,x]!=1: return False
                        k+=1
                if sees(*d) and sees(-d[0],-d[1]):
                    res[i,j]=True; break
    return res
