from collections import Counter
def rule_gen(G):
    cnt = Counter(G.flatten())
    bg = cnt.most_common(1)[0][0]
    marks = [v for v in cnt if v!=bg]
    # assume single mark color
    m = marks[0] if len(marks)==1 else None
    Hh,Ww = G.shape; R = G.copy()
    for rrr in range(Hh):
        twos = [c for c in range(Ww) if G[rrr,c]==m]
        for a1,b1 in zip(twos,twos[1:]):
            if all(G[rrr,c]==bg for c in range(a1+1,b1)):
                for c in range(a1+1,b1): R[rrr,c]=3
    for ccc in range(Ww):
        twos = [r for r in range(Hh) if G[r,ccc]==m]
        for a1,b1 in zip(twos,twos[1:]):
            if all(G[r,ccc]==bg for r in range(a1+1,b1)):
                for r in range(a1+1,b1): R[r,ccc]=3
    return R
